def tab(t,h,r,n=None):return ('table',t,h,r,n)
def p(t):return ('p',t)
def packnum(n):return str(int(n)) if float(n).is_integer() else M.f(n,2)
def card(t,ls):return ('cards',[(t,None,ls)])
def links(ids,main=False):return ('links','Расчёты ремонта',[(x['name'],('' if main else '../')+x['id']+'/index.html',x['about']) for x in PAGES if x['id'] in ids])
