def sources_data():
 path=M.ROOT/'procurement_sources.json'
 return json.loads(path.read_text()) if path.exists() else {}

def source_html(id,src):
 ss=src.get(id,{}).get('links',[])
 return '<br>'.join(f'<a href="{E(s["url"],quote=True)}">{i+1}. {E(s["label"])}</a>' for i,s in enumerate(ss)) or 'Источники подбираются'

def build(e):
 rows=M.takeoff(e);g=M.geometry();t=M.totals(rows);labor=M.labor_rows();src=sources_data()
 room_totals,room_work=M.room_budget(e,rows)
 write_exports(rows,src,room_totals,room_work)
 stage=[]
 for id,name,days,scope in M.STAGES:
  material=sum(x['cost'] for x in rows if x['stage']==int(id));work=sum(x['cost'] for x in labor if x['stage']==int(id))
  stage.append([id,name,days,M.money(material),M.money(work),M.money(material+work),scope])
 roomlinks=[(name,f'{r}/index.html','Геометрия, расход материалов и мебель этой комнаты') for r,name in M.ROOM_NAMES.items() if r!='common']
 summary=[['Материалы, оборудование, мебель',M.money(t['materials'])+' ₽','Сумма выбранных бюджетных допусков по упаковкам'],['Работы',M.money(t['labor'])+' ₽','Отдельные предварительные ставки, не договор подрядчика'],['Доставка, подъём, вывоз',M.money(t['logistics'])+' ₽','3,5% товарного бюджета — плановый допуск'],['Резерв неопределённости',M.money(t['contingency'])+' ₽','12% от материалов + работ + логистики'],['Всего с резервом',M.money(t['total'])+' ₽','Плановый сценарий, не коммерческая смета']]
 rooms={}
 for room in e['ROOM_ORDER']:
  d=g[room];rr=[r for r in rows if room in r['room_qty']];cost=sum(r['room_cost'].get(room,0) for r in rr)
  roomstage=[[id,name,M.money(sum(r['room_cost'].get(room,0) for r in rr if r['stage']==int(id)))+' ₽'] for id,name,*_ in M.STAGES]
  blocks=[p(f'Площадь по контуру {M.f(d["area"],2)} м²; периметр {M.f(d["perimeter"],2)} м. Нетто стен под отделку {M.f(d["wall"],2)} м² при условной чистой высоте {M.f(M.CLEAR_HEIGHT,2)} м. Товарный бюджет комнаты {M.money(cost)} ₽; общие сети и работы показаны отдельно.'),
   tab('Бюджет комнаты',['Статья','Доля, ₽'],[[name,M.money(room_totals[room][key])] for key,name in [('materials','Товары'),('labor','Работы'),('logistics','Логистика'),('contingency','Резерв'),('total','ИТОГО')]],'Работы распределены для планирования по площади/точкам/приборам. Фактическое предложение подрядчика может иметь другую разбивку.'),
   tab('Стоимость закупок по этапам',['№','Этап','Доля комнаты'],roomstage),
   tab('Работы комнаты',['Этап','Работа','Доля, ₽','Основание'],[[str(x['stage']),x['name'],M.money(x['room_cost'][room]),x['basis']] for x in room_work if room in x['room_cost']]),
   tab('Материалы, оборудование и мебель комнаты',['Код','Позиция','Нетто комнаты','Ед.','Доля общих закупок, ₽','Где купить'],
    [[f'<a href="../zakupki/#sku-{r["id"]}">{r["id"]}</a>',r['name'],M.f(r['room_qty'][room],2),r['unit'],M.money(r['room_cost'][room]),source_html(r['id'],src)] for r in rr],
    'Доля стоимости включает пропорционально запас и округление общей закупки до упаковок. Это не заказ упаковок на комнату: корзину собирать по общей ведомости.'),links(['konstrukcii','etapy','byudzhet','zakupki']),
    ('links','Инженерные точки комнаты',[(s, f'../../{id}/{room}/index.html','Координаты, высоты, маркировка') for id,s in [('elektrika','Электрика'),('santehnika','Вода и канализация'),('slabotochka','Слаботочка')]])]
  rooms[room]=blocks
